// Pseudo-test scaffold to validate cross-tenant data isolation
function testTenantIsolation(tenantA, tenantB) {
  const dA = query(tenantA, 'billing');
  const dB = query(tenantB, 'billing');
  assert(dA.tenantId === tenantA.id);
  assert(dB.tenantId === tenantB.id);
  assert(!dA.data.includes(tenantB.id));
  assert(!dB.data.includes(tenantA.id));
}
```

